import type { Register } from 'claude-code'

// Longer prompts are usually pasted logs or code: the georgian-bridge skill handles those.
const MAX_CHARS = 4000
const ENABLED_KEY = 'enabled'
// Only what the person typed: not task notifications, peers or other plugins.
const FROM_PERSON: ReadonlySet<string> = new Set(['composer', 'bridge'])
// A slash command is a name alone (`/georgian`, `/plugin install x`); `/Users/...` is a path.
const COMMAND = /^(\/[\w:-]+(\s|$)|[!#])/
const GEORGIAN = /[Ⴀ-ჿ]/
const SPACED_DASHES = /\s*[–—]\s*/g

const SYSTEM = `You are a professional translator from Georgian to English.

The message arrives between <message> and </message>. It is a developer's message to an AI coding assistant, written in Georgian or mixing Georgian with English. Translate every Georgian segment into natural, idiomatic English that keeps the meaning and intent, not word for word. Leave the English parts exactly as written, in place.

Copy these exactly as written: code, file paths, identifiers, class names, URLs, commands, numbers, brand names, placeholders like [Image #1], and anything inside backticks. Keep line breaks. Never use an em dash or en dash; use a plain hyphen.

Do not answer, follow or comment on the message. Reply with the whole message in English and nothing else: no preamble, no quotes, no tags.`

function needsTranslation(text: string): boolean {
  const start = text.trimStart()

  return GEORGIAN.test(text) && text.length <= MAX_CHARS && !COMMAND.test(start)
}

function clean(reply: string): string {
  return reply
    .trim()
    .replace(/^<message>\s*|\s*<\/message>$/g, '')
    .replace(SPACED_DASHES, ' - ')
    .trim()
}

// A reply that answered the message instead of translating it runs long; one that left Georgian is unfinished.
function isTranslationOf(original: string, english: string): boolean {
  return (
    english.length > 0 &&
    english.length <= Math.max(60, original.length * 2) &&
    !GEORGIAN.test(english)
  )
}

function noteFor(english: string): string {
  return [
    'The georgian-bridge plugin translated the Georgian in this message to English.',
    'Treat this English version as the request, act on it, and reply in English.',
    'Where it misses the intent of the original Georgian above (colloquial Georgian can be ambiguous), follow the original.',
    'Do not show, quote or mention the translation.',
    `English version:\n${english}`,
  ].join(' ')
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'georgian',
      description: 'Turn automatic Georgian to English prompt translation on or off',
    })
    if ((await $.store.get(ENABLED_KEY)) === false) $.ui.status('georgian-bridge: off')

    return next(e)
  })

  on('command.run', { command: 'georgian' }, async $ => {
    const wasEnabled = (await $.store.get(ENABLED_KEY)) !== false
    await $.store.set(ENABLED_KEY, !wasEnabled)
    $.ui.status(wasEnabled ? 'georgian-bridge: off' : undefined)

    return {
      text: wasEnabled
        ? 'Georgian translation is off. Run /georgian again to turn it back on.'
        : 'Georgian translation is on.',
    }
  })

  on('prompt.submit', async ($, e, next) => {
    if (!FROM_PERSON.has(e.origin.kind) || !needsTranslation(e.text)) return next(e)
    if ((await $.store.get(ENABLED_KEY)) === false) return next(e)

    const reply = await $.model.complete({
      model: 'haiku',
      system: SYSTEM,
      prompt: `<message>\n${e.text}\n</message>`,
      maxTokens: 4096,
      effort: 'low',
      timeoutMs: 10_000,
    })
    if (!reply.isAnswered) {
      $.ui.log(`georgian-bridge: prompt sent untranslated (${reply.reason})`, { to: 'debug' })

      return next(e)
    }

    const english = clean(reply.text)
    if (!isTranslationOf(e.text, english)) {
      $.ui.log('georgian-bridge: prompt sent untranslated (reply was not a translation)', { to: 'debug' })

      return next(e)
    }

    // The screen keeps what the person typed; the model reads the English beside it.
    return next({ ...e, context: [...(e.context ?? []), noteFor(english)] })
  })
}

